27			t.Fatalf("failed import returned a partial graph %v, want nil", graph)
28		}
29		msg := err.Error()
30		for _, want := range []string{"unpaired Unicode surrogate escape", location, escape} {
31			if !strings.Contains(msg, want) {
32				t.Errorf("error %q must contain %q", msg, want)
33			}
34		}
35		if strings.ContainsRune(msg, '�') {
36			t.Errorf("error %q must not render the bad escape as a replacement character", msg)
37		}
