233	// a legal non-empty name) and escapes standing next to paired surrogates.
234	func TestImportLineageOrdinaryUEscapesStillDecode(t *testing.T) {
235		text := `{"nodes":["\u4e2d\u6587","x\u0041","\u0000","\ud83d\ude00"],` +
236			`"edges":[{"from":"\u4e2d\u6587","to":"x\u0041"},` +
237			`{"from":"\ud83d\ude00","to":"x\u0041"}]}`
238		graph := mustImport(t, text)
